-- Juris — Supabase / Postgres schema
-- Mirrors the original SQLite schema. IDs are UUID strings generated by the app,
-- timestamps are ISO-8601 strings, and JSON blobs are stored as text so the
-- application layer stays portable between SQLite and Postgres.

create table if not exists users (
  id text primary key,
  email text not null unique,
  password_hash text not null,
  name text not null,
  created_at text not null
);

create table if not exists sessions (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

create table if not exists reset_tokens (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  expires_at timestamptz not null,
  used_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists profiles (
  user_id text primary key references users(id) on delete cascade,
  course text not null,
  year_label text not null,
  subjects text not null,
  goal text not null,
  daily_minutes integer not null,
  onboarded_at text
);

create table if not exists documents (
  id text primary key,
  owner_id text references users(id) on delete cascade,
  kind text not null,
  title text not null,
  subtitle text,
  citation text,
  court text,
  year integer,
  subject text,
  jurisdiction text,
  doc_type text,
  source_url text,
  official_text text,
  explanation text,
  brief text,
  meta text not null default '{}',
  verification text not null,
  created_at text not null
);

create table if not exists bookmarks (
  user_id text not null references users(id) on delete cascade,
  document_id text not null references documents(id) on delete cascade,
  created_at text not null,
  primary key (user_id, document_id)
);

create table if not exists notes (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  document_id text not null references documents(id) on delete cascade,
  body text not null,
  created_at text not null,
  updated_at text not null
);

create table if not exists highlights (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  document_id text not null references documents(id) on delete cascade,
  text text not null,
  note text,
  created_at text not null
);

create table if not exists scan_jobs (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  title text not null,
  status text not null default 'draft',
  pages text not null default '[]',
  raw_text text not null default '',
  error text,
  document_id text,
  created_at text not null,
  updated_at text not null
);

create table if not exists flashcards (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  document_id text references documents(id) on delete set null,
  front text not null,
  back text not null,
  source text,
  ease double precision not null default 2.5,
  interval_days integer not null default 0,
  due_at text not null,
  reps integer not null default 0,
  lapses integer not null default 0,
  created_at text not null
);

create table if not exists review_logs (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  card_id text not null,
  rating integer not null,
  prev_interval integer not null,
  reviewed_at text not null
);

create table if not exists quizzes (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  document_id text,
  title text not null,
  subject text,
  questions text not null,
  created_at text not null
);

create table if not exists quiz_attempts (
  id text primary key,
  quiz_id text not null references quizzes(id) on delete cascade,
  user_id text not null references users(id) on delete cascade,
  answers text not null,
  score integer not null,
  total integer not null,
  created_at text not null
);

create table if not exists conversations (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  title text not null,
  document_id text,
  created_at text not null,
  updated_at text not null
);

create table if not exists messages (
  id text primary key,
  conversation_id text not null references conversations(id) on delete cascade,
  role text not null,
  content text not null,
  citations text not null default '[]',
  created_at text not null
);

create table if not exists deadlines (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  title text not null,
  subject text,
  due_at text not null,
  notes text,
  completed integer not null default 0,
  created_at text not null
);

create table if not exists activities (
  id text primary key,
  user_id text not null references users(id) on delete cascade,
  kind text not null,
  label text not null,
  ref_id text,
  created_at text not null
);

create index if not exists idx_documents_kind on documents(kind);
create index if not exists idx_documents_owner on documents(owner_id);
create index if not exists idx_flashcards_due on flashcards(user_id, due_at);
create index if not exists idx_activities_user on activities(user_id, created_at);
create index if not exists idx_scan_jobs_user on scan_jobs(user_id);
create index if not exists idx_sessions_user on sessions(user_id);
create index if not exists idx_messages_conversation on messages(conversation_id, created_at);
create index if not exists idx_notes_document on notes(user_id, document_id);
create index if not exists idx_highlights_document on highlights(user_id, document_id);

-- The app talks to Postgres with the `postgres` role and does its own
-- authorisation, so the Data API roles must not see these tables at all.
revoke all on all tables in schema public from anon, authenticated;
alter default privileges in schema public revoke all on tables from anon, authenticated;

alter table users enable row level security;
alter table sessions enable row level security;
alter table reset_tokens enable row level security;
alter table profiles enable row level security;
alter table documents enable row level security;
alter table bookmarks enable row level security;
alter table notes enable row level security;
alter table highlights enable row level security;
alter table scan_jobs enable row level security;
alter table flashcards enable row level security;
alter table review_logs enable row level security;
alter table quizzes enable row level security;
alter table quiz_attempts enable row level security;
alter table conversations enable row level security;
alter table messages enable row level security;
alter table deadlines enable row level security;
alter table activities enable row level security;
